// ASYNC

export const typeCheckTsFile = async (
		path: string
		): AutoPromise<void> => {

	const cmd = new Deno.Command('deno', {
		args: ["check", path],
		stdout: "piped",
		stderr: "piped"
		})

	const {success, stderr} = await cmd.output()
	if (success) {
		return
	}
	else {
		croak(new TextDecoder().decode(stderr))
	}
}

